*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_pf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//scwin.pMenuID = $c.win.getProgramId();
scwin.fr_SecuGrpId = $c.lc.getGlbValue("SECUGRP_ID_PF");
scwin.fr_MktId = $c.session.getUserInfo("market");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.spacYN = "N";
scwin.vScrenID = "ULDSTF09324.xml";
scwin.chkRowIndex = 0;
scwin.hist_bz_procs_no = "";
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y";
scwin.onpageload = function() {
    scwin.init();
};
scwin.onpageunload = function() {
};
scwin.fn_search = async function() {
    // var url = "/pf/administrativeIssue.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchAdministrativeIssue" + "&DIV_IDX=" + DIV_IDX_ADMISU_LIST + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + scwin.vIsurCd;
    // dlt_listRes.DataID = encodeURI(url);
    // dlt_listRes.reset();
    // $c.cm.ShowWin(grd_List);

    const sbmOptions = {
        id: "sbm_selectOneIsuInfo",
        action: "/api/listing/lstproc/pf/admisu-design/select-list?isurCd="+scwin.vIsurCd,
        method: "get",
        target: "dlt_listRes=body",
        isProcessMsg: false
    };
    let res = await $c.sbm.executeDynamic(sbmOptions);
    debugger;
};
scwin.fn_GetParIsur = function(arrPar) {
    arrPar[0] = "";
    arrPar[1] = txb_ISU_NM.getValue();
    arrPar[2] = scwin.fr_SecuGrpId;
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }
    scwin.fn_search();
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD == "D") {
        img_Regist.setDisabled(true);
        img_Regist.src = "../img/btn_new_d.gif";
    } else {
        img_Regist.setDisabled(false);
        img_Regist.src = "../img/btn_new.gif";
    }
};
scwin.fn_GetParUpdate = function(arrPar) {
    arrPar[0] = scwin.vIsurCd;
    arrPar[1] = txb_ISU_NM.getValue();
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "bz_procs_no");
    arrPar[5] = dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "ADMISU_DESIGN_BZ_TP_CD");
    arrPar[6] = txb_ISU_CD.getValue();
    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    arrPar[0] = scwin.vIsurCd;
    arrPar[1] = txb_ISU_NM.getValue();
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = "";
    arrPar[5] = cmb_RegistTyp.BindColVal;
    arrPar[6] = txb_ISU_CD.getValue();
};
scwin.fn_newpre_create_frame = async function(arg) {
    /*
    0:관리종목지정
    1:관리종목사유변경
    2:관리종목사유및상장폐지기준일변경
    3:상장폐지기준일변경
    4:관리종목지정해제
    */
    var urlId = "";
    var title = "";
    switch (arg) {
        case "0":
            urlId = "ULDSTF09325";
            title = "관리종목지정";
            //await $c.frame.CreateDialogFrame("DLG_0", "../pf/ULDSTF09325.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정", 200, 50, 620, 370, "window");
            break;
        case "1":
            urlId = "ULDSTF09326";
            title = "관리종목지정 사유변경";
            //await $c.frame.CreateDialogFrame("DLG_1", "../pf/ULDSTF09326.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정 사유변경", 200, 50, 620, 520, "window");
            break;
        case "4":
            urlId = "ULDSTF09327";
            title = "관리종목지정 해제";
            //await $c.frame.CreateDialogFrame("DLG_2", "../pf/ULDSTF09327.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정 해제", 200, 50, 620, 450, "window");
            break;
    }

    var data = {};

    const opts = {
        id: urlId,
        popupName: title,
        width: 600,
        height: 640,
        frameModal: "top",
    };

    var res = await $c.win.openPopup("/ui/lst/pf/" + urlId + ".xml", opts, data);

    cmb_RegistTyp.setSelectedIndex(0);
};
scwin.img_Excel_onclick = function() {
    if (dlt_listRes.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "관리종목지정내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Search_onclick = function() {
    if (scwin.vIsurCd != "") {
        scwin.fn_search();
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
    }
};
// scwin.dlt_listRes_OnLoadError = function() {
//     $c.stf.alert_error(dlt_listRes);
// };
scwin.dlt_listRes_OnLoadCompleted = function(rowcount) {
    $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    //$c.cm.CloseWin(rowcount, grd_List);
};
/* scwin.img_Close_onclick = function() {
    window.close();
}; */
scwin.img_Regist_onclick = function() {
    if (txb_ISU_CD.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
        return true;
    }
    if (cmb_RegistTyp.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
        cmb_RegistTyp.focus();
        return true;
    }
    //scwin.fn_GetPar = fn_GetParNew;
    //scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame(cmb_RegistTyp.getValue());
};
scwin.grd_List_OnDblClick = function(row, colid) {
    //scwin.fn_GetPar = fn_GetParUpdate;
    //scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame(dlt_listRes.getCellData(dlt_listRes.getRowPosition(), "admisuDesignBzTpCd"));
};
scwin.init = function() {
    //$c.libRoundPanel.PanelToGroupBox(panel_Top);
};
scwin.btn_iSU_CD_onclick = async function() {
    //scwin.fn_GetPar = scwin.fn_GetParIsur;
    //scwin.fn_SetPar = scwin.fn_SetParIsur;
    //$c.lcp.popFindIsuAll(scwin.fr_SecuGrpId);
    const data = {
        secugrpId: scwin.fr_SecuGrpId,
    };
    //const res = await $c.lc.popFindIsuAll(data);
    const res = await $c.lc.popFindIsu(data);


    if(typeof res.isuCd != 'undefined') {
        txb_ISU_CD.setValue(res.isuCd);
        txb_ISU_NM.setValue(res.isuKorNm);
        scwin.vIsurCd = res.isurCd;

        scwin.fn_search();

        scwin.vLIST_STAT_CD = res.listStatCd;
        if (scwin.vLIST_STAT_CD == "D") {
            img_Regist.setDisabled(true);
        } else {
            img_Regist.setDisabled(false);
        }
    }
};
